<?php declare(strict_types=1); namespace Modules\PromptEngine\Console; use Illuminate\Console\Command; use Modules\PromptEngine\Services\PromptEngineService; final class GenerateCharacterImageCommand extends Command { protected $signature='prompt-engine:generate-image {character} {--provider=gemini} {--style=museum-editorial} {--aspect-ratio=2:3} {--save}'; protected $description='Generate and store an educational Chinese-character image'; public function handle(PromptEngineService $engine):int{$r=$engine->generate(['character'=>$this->argument('character'),'platform'=>$this->option('provider'),'style'=>$this->option('style'),'aspect_ratio'=>$this->option('aspect-ratio'),'mode'=>'generate_image','save'=>$this->option('save')]);$this->line(json_encode($r->toArray(),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'{}');return self::SUCCESS;} }
